function validate([s, k]) {
  if (k < 1 || k > 100) return 'k is from 1 to 100.';
  if (s.length < k || s.length > 1000) return 's needs between k and 1000 characters.';
  if (s.length % k !== 0) return 'The length of s must be a multiple of k.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  return null;
}

