function stringHash(s, k) {
  const base = 'a'.charCodeAt(0);
  let result = '';
  for (let start = 0; start < s.length; start += k) {
    let sum = 0;
    for (let i = start; i < start + k; i++) {
      sum += s.charCodeAt(i) - base;
    }
    const hashedChar = sum % 26;
    result += String.fromCharCode(base + hashedChar);
  }
  return result;
}

