function stringHash(s, k) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const out = [];
  let total = 0;
  // One pass: close a block whenever k letters have been added.
  for (let i = 0; i < s.length; i++) {
    total += alphabet.indexOf(s[i]);
    if ((i + 1) % k === 0) {
      out.push(alphabet[total % 26]);
      total = 0;
    }
  }
  return out.join('');
}

