function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const k = size === 'small' ? int(1, 4) : int(1, 100);
  const blocks = size === 'small' ? int(1, 5) : Math.floor(1000 / k);
  // Sometimes use only a few letters (including the extremes), sometimes the whole alphabet.
  const roll = rand();
  const letters = roll < 0.25 ? 'az' : roll < 0.45 ? 'xyz' : 'abcdefghijklmnopqrstuvwxyz';
  let s = '';
  for (let i = 0; i < k * blocks; i++) s += letters[int(0, letters.length - 1)];
  return [s, k];
}
